function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  const small = size === 'small';
  const count = small ? 1 + pick(10) : 900 + pick(80);
  const span = small && rand() < 0.8 ? 20 : 10000;
  // Distinct values inserted in random order give a random BST shape.
  const seen = new Set();
  const order = [];
  while (order.length < count) {
    const value = pick(2 * span + 1) - span;
    if (seen.has(value)) continue;
    seen.add(value);
    order.push(value);
  }
  // Sorted insertion order makes a chain.
  if (small && rand() < 0.2) { const rising = rand() < 0.5; order.sort((a, b) => (rising ? a - b : b - a)); }
  let root = null;
  for (const value of order) {
    const node = { val: value, left: null, right: null };
    if (!root) { root = node; continue; }
    let at = root;
    for (;;) {
      const side = value < at.val ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  // k: a real pair's sum, twice one value (the same node may not be reused), out of reach, or random.
  const style = rand();
  let k;
  if (style < 0.4 && count > 1) {
    const i = pick(count);
    let j = pick(count - 1);
    if (j >= i) j++;
    k = order[i] + order[j];
  } else if (style < 0.6) k = 2 * order[pick(count)];
  else if (style < 0.7) k = rand() < 0.5 ? 100000 : -100000;
  else k = pick(4 * span + 1) - 2 * span;
  return [out, k];
}
